        RessumoResponse response = (RessumoResponse) service.calcular(request);

        assertEquals("399.80", response.subtotalProdutos.toString());
        assertEquals("50.00", response.descontoCupom.toString());
        assertEquals("18.00", response.frete.toString());
        assertEquals(0, response.prazoEntregaDias);
        assertEquals("8.00", response.seguro.toString());
        assertEquals("3.49", response.ajustePagamento.toString());
        assertEquals("379.29", response.totalFinal.toString());
        assertEquals(1, response.parcelas);
        assertEquals("379.29", response.valorParcela.toString());
        assertEquals("0.00", response.creditoProximaCompra.toString());
        assertFalse(response.brinde);
    }

    @Test
    public void exemplo4() {
        RessumoRequest request = new RessumoRequest();
        request.itens = Arrays.asList(
            new Item("Meia", 19.90, 7, 0.10),
            new Item("Camiseta", 79.90, 2, 0.30)
        );
        request.modalidadeEntrega = ModalidadeEntrega.RETIRADA_LOJA;
        request.cupom = "LEVE3PAGUE2";
