        RessumoResponse response = (RessumoResponse) service.calcular(request);

        assertEquals("299.10", response.subtotalProdutos.toString());
        assertEquals("39.80", response.descontoCupom.toString());
        assertEquals("0.00", response.frete.toString());
        assertEquals(1, response.prazoEntregaDias);
        assertEquals("2.99", response.seguro.toString());
        assertEquals("0.00", response.ajustePagamento.toString());
        assertEquals("262.29", response.totalFinal.toString());
        assertEquals(3, response.parcelas);
        assertEquals("87.43", response.valorParcela.toString());
        assertEquals("5.98", response.creditoProximaCompra.toString());
        assertFalse(response.brinde);
