    @Test
    public void exemplo5() {
        RessumoRequest request = new RessumoRequest();
        request.itens = Arrays.asList(
            new Item("Camiseta", 79.90, 2, 0.30),
            new Item("Tênis", 249.90, 1, 1.20)
