        assertEquals("409.70", response.subtotalProdutos.toString());
        assertEquals("0.00", response.descontoCupom.toString());
        assertEquals("0.00", response.frete.toString());
        assertEquals(2, response.prazoEntregaDias);
        assertEquals("4.10", response.seguro.toString());
        assertEquals("-20.69", response.ajustePagamento.toString());
        assertEquals("393.11", response.totalFinal.toString());
        assertEquals(1, response.parcelas);
        assertEquals("393.11", response.valorParcela.toString());
        assertEquals("20.48", response.creditoProximaCompra.toString());
        assertFalse(response.brinde);
    }
}

